/**
 * Mini-assessment items. "Show calculation" text is generated by the engine at
 * runtime (never hard-coded numbers).
 */
import { calculate, fisherApprox, fisherNominal } from '../lib/finance';
import { formatPctChange, formatRate, formatSpotUnit } from '../lib/format';
import { PRESETS } from '../lib/scenarios';
import type { TopicId } from './topics';

export type QuizOption = { id: string; text: string };

export type QuizItem = {
  id: string;
  question: string;
  options: QuizOption[];
  correct: string;
  /** One sentence shown right after answering. */
  feedback: string;
  /** Learn More topic behind "See why →". */
  topic: TopicId;
  explanation: string;
  calculation: () => string[];
};

export const QUIZ: QuizItem[] = [
  {
    id: 'q1',
    question:
      'US expected inflation rises while Malaysian expected inflation stays fixed (equal real rates, same spot rate). In this model, what happens to the PPP-implied MYR/USD rate?',
    options: [
      { id: 'a', text: 'It rises — the ringgit depreciates' },
      { id: 'b', text: 'It falls — the ringgit appreciates' },
      { id: 'c', text: 'It stays the same' },
      { id: 'd', text: 'It cannot be determined from PPP' },
    ],
    correct: 'b',
    feedback: 'US inflation sits in the denominator of the PPP ratio, so MYR/USD falls and the ringgit strengthens in the model.',
    topic: 'ppp',
    explanation:
      'US inflation sits in the denominator of S₀ × (1 + π_MY)/(1 + π_US). A bigger denominator gives a smaller MYR/USD number: USD 1 costs fewer ringgit, so the MYR appreciates — within the model only.',
    calculation: () => {
      const a = calculate(PRESETS.A.inputs);
      const b = calculate(PRESETS.B.inputs);
      return [
        `Baseline (π_US 3.00%): 4.4 × 1.025/1.03 = ${formatSpotUnit(a.pppSpot)}`,
        `π_US raised to 5.00%: 4.4 × 1.025/1.05 = ${formatSpotUnit(b.pppSpot)} (${formatPctChange(b.quoteChangePct)} vs S₀)`,
      ];
    },
  },
  {
    id: 'q2',
    question: 'MYR/USD moves from 4.4000 to 4.5073. Did the ringgit strengthen or weaken?',
    options: [
      { id: 'a', text: 'Strengthened — the number went up' },
      { id: 'b', text: 'Neither — only the US dollar changed' },
      { id: 'c', text: 'Weakened — USD 1 now costs more ringgit' },
      { id: 'd', text: 'It depends on the forward rate' },
    ],
    correct: 'c',
    feedback: 'A higher MYR/USD means US$1 costs more ringgit, so the ringgit weakened.',
    topic: 'reading-rates',
    explanation:
      'MYR/USD is the number of ringgit paid for one US dollar. A higher number means each dollar costs more ringgit, so the ringgit is weaker (it depreciated).',
    calculation: () => {
      const d = calculate(PRESETS.D.inputs);
      return [
        `Scenario D (π_MY 5.00%, π_US 2.50%): S₁ = 4.4 × 1.05/1.025 = ${formatSpotUnit(d.pppSpot)}`,
        `Quote change = ${formatPctChange(d.quoteChangePct)}; MYR value in USD = ${formatPctChange(d.myrValueChangePct)}`,
      ];
    },
  },
  {
    id: 'q3',
    question: 'The real interest rate is 1.5% and expected inflation is 2.5%. What is the exact Fisher-implied nominal rate?',
    options: [
      { id: 'a', text: '4.0000%' },
      { id: 'b', text: '3.9000%' },
      { id: 'c', text: '1.0000%' },
      { id: 'd', text: '4.0375%' },
    ],
    correct: 'd',
    feedback: `Exact Fisher gives (1.015)(1.025) − 1 = ${formatRate(fisherNominal(0.015, 0.025) * 100)}; the shortcut r + π misses the cross-term.`,
    topic: 'fisher',
    explanation:
      'Exact Fisher: i = (1 + r)(1 + π) − 1. The shortcut r + π = 4.0% ignores the cross-term r × π. 1.0% is π − r, which mixes up the relationship.',
    calculation: () => [
      `i = (1.015)(1.025) − 1 = ${formatRate(fisherNominal(0.015, 0.025) * 100)}`,
      `Approximation r + π = ${formatRate(fisherApprox(0.015, 0.025) * 100)} (comparison only)`,
    ],
  },
  {
    id: 'q4',
    question: 'Is the covered-IRP forward rate a guaranteed forecast of the future spot rate?',
    options: [
      { id: 'a', text: 'Yes — it is what the spot rate will be in one year' },
      { id: 'b', text: 'No — it is a contract price set by no-arbitrage, not a forecast' },
      { id: 'c', text: 'Yes, whenever PPP gives the same number' },
      { id: 'd', text: 'No — it is the central bank’s policy rate' },
    ],
    correct: 'b',
    feedback: 'A forward is a price agreed today under no-arbitrage, not a forecast of the future spot rate.',
    topic: 'covered-irp',
    explanation:
      'A forward is a price agreed today for a future exchange. Covered IRP prices it from today’s spot and interest rates so that hedged investing earns the same at home and abroad. The future spot rate can end up very different.',
    calculation: () => {
      const a = calculate(PRESETS.A.inputs);
      return [
        `F = S₀ × (1 + i_MY)/(1 + i_US) = 4.4 × 1.040375/1.04545 = ${formatSpotUnit(a.cipForward)}`,
        'This uses only today’s spot and interest rates — no information about the future spot rate.',
      ];
    },
  },
  {
    id: 'q5',
    question: 'Why do the PPP-implied spot and the CIP forward give the same number in core mode?',
    options: [
      { id: 'a', text: 'Because forward rates always equal future spot rates' },
      { id: 'b', text: 'Because the spot rate is fixed at 4.4000' },
      { id: 'c', text: 'Because the common real rate (1 + r) cancels in the ratio' },
      { id: 'd', text: 'Because both countries have the same inflation' },
    ],
    correct: 'c',
    feedback: 'With one shared real rate, the (1 + r) factors cancel and leave exactly the PPP ratio.',
    topic: 'forward-equals-ppp',
    explanation:
      '(1 + i_MY)/(1 + i_US) = (1 + r)(1 + π_MY) / [(1 + r)(1 + π_US)]. With the same r in both countries, (1 + r) cancels, leaving the PPP ratio. With different real rates they separate.',
    calculation: () => {
      const adv = calculate(PRESETS.ADV.inputs);
      return [
        '(1.015 × 1.025)/(1.015 × 1.03) = 1.025/1.03 → PPP = CIP',
        `If r_US = 2.5% instead: CIP = ${formatSpotUnit(adv.cipForward)} vs PPP = ${formatSpotUnit(adv.pppSpot)}`,
      ];
    },
  },
];
